      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-wsl-eventlog\",\n  \"version\": \"0.1.0\",\n  \"description\": \"Read recent Windows event log entries from WSL, by log name and level.\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/173787247/dsh-wsl-eventlog.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/173787247/dsh-wsl-eventlog/issues\"\n  },\n  \"homepage\": \"https://github.com/173787247/dsh-wsl-eventlog#readme\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"scripts\": {\n    \"test\": \"node --test test/*.test.js\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"LICENSE\"\n  ],\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"wsl\",\n    \"windows\",\n    \"eventlog\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  }\n}\n"
